class TriangleError(Exception):
    """异常类，用于当三角形的边长不满足任意两边之和大于第三边时抛出异常"""
    def __init__(self, message):
        # 调用父类Exception的__init__方法，设置异常信息
        super().__init__(message)
# 使用自定义的异常类
def check_triangle(a, b, c):
    if a <= 0 or b <= 0 or c <= 0:
        raise TriangleError("边长需要大于0")
    if a + b <= c or a + c <= b or b + c <= a:
        raise TriangleError("任意两边之和不大于第三边，不能构成三角形")
# 测试异常
try:
    check_triangle(1, 2, 3)  # 正确的边长，不会抛出异常
    check_triangle(1, 2, 1)  # 不正确的边长，会抛出异常
except TriangleError as e:
    print(e)

